    case ENTITY_CONGLOMERATE:
    {
      conglomerate *conglom = (conglomerate *)owner;

      entity *node = conglom->get_member(limb);
      if ( node )
        link_ifc()->set_parent( node );
      else
        link_ifc()->set_parent( owner );
    }
    break;

    default:
    {
      link_ifc()->set_parent(owner);
    }
    break;
  }

  set_rel_po(offset);

  set_visible(true);
}
